svg.script:
(function () {
  var DUR = 8000;

var el = document.getElementById('nba-hero-num');
function renderAt(p) {
  if (!el) return;
  var s = Math.sin(2 * Math.PI * p) + 0.35 * Math.sin(4 * Math.PI * p);
  el.textContent = (530.7 + 16.4 * s).toFixed(1) + 'M';
}

  var manual = false;
  window.__seekSvgTime = function (tMs) {
    manual = true;
    renderAt((((tMs / DUR) % 1) + 1) % 1);
  };
  renderAt(0);
  if (typeof requestAnimationFrame === 'function') {
    var t0 = performance.now();
    function loop(now) {
      if (manual) return;
      renderAt(((now - t0) % DUR) / DUR);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  }
})();
